#!/bin/bash
# CLAUDE S81-RERUN v8: route SDC of the selector / collector crossing stage dsfd_xstg_515 (d8g1 meso FIFO, pins
# registered).  usage: make_sdc_xstg.sh <L_ps> <out.sdc>
# Clocks: ck (band block region, core_clk) and cw (end block region, wclk): equal period, bounded static phase
# (<= 385 ps): the meso crossing arcs carry 1.5 T - 60 = 1,190 ps (d8g1, as make_sdc_cfifo.sh).
# IO: i registered at the pin in cw (0.2 T against vw); o launched from a flop in ck (0.2 T + 150 ps die term).
L=${1:?L}; O=${2:?out}
cat > $O <<EOT
# generated by physical/s81_die_views/glue/make_sdc_xstg.sh $L
create_clock -name core_clk -period 833.333 [get_ports {ck[0]}]
create_clock -name wclk -period 833.333 [get_ports {cw[0]}]
create_clock -name vclk -period 833.333
create_clock -name vw -period 833.333
set_clock_latency $L [get_clocks {vclk vw}]
set_clock_uncertainty -setup 123 [all_clocks]
set_clock_uncertainty -hold 25 [all_clocks]
set_max_delay -ignore_clock_latency 1190.0 -from [get_clocks wclk] -to [get_clocks core_clk]
set_max_delay -ignore_clock_latency 1190.0 -from [get_clocks core_clk] -to [get_clocks wclk]
set_min_delay -ignore_clock_latency 0 -from [get_clocks wclk] -to [get_clocks core_clk]
set_min_delay -ignore_clock_latency 0 -from [get_clocks core_clk] -to [get_clocks wclk]
set_false_path -from [get_clocks vw] -to [get_clocks {core_clk vclk}]
set_false_path -from [get_clocks vclk] -to [get_clocks {wclk vw}]
set_false_path -from [get_clocks wclk] -to [get_clocks vclk]
set_false_path -from [get_clocks core_clk] -to [get_clocks vw]
set_input_delay 166.667 -clock vw [get_ports {i*}]
set_input_delay -min 0 -clock vw [get_ports {i*}]
set_output_delay 316.667 -clock vclk [get_ports {o*}]
set_output_delay -min 0 -clock vclk [get_ports {o*}]
set_max_fanout 32 [current_design]
EOT
